import{_ as a,c as t,o,af as r}from"./chunks/framework.CQaL6XNJ.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"ESA Antarctica Datacube Dashboard","tagline":"Antarctica International Science & Infrastructure for Synchronous Observation","text":""}},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),i={name:"index.md"};function n(s,e,c,d,l,h){return o(),t("div",null,[...e[0]||(e[0]=[r('<p>As part of an EarthCODE initiative to facilitate easier analysis of and access to EO Earth Sciences data, several datasets are combined into analysis ready zarr data cubes.</p><p>Putting datasets on a common projection, resolution, and coordinate system reduces the amount of preprocessing needed before analysis.</p><h2 id="land-ice-data-collections-overview" tabindex="-1">Land Ice Data Collections Overview <a class="header-anchor" href="#land-ice-data-collections-overview" aria-label="Permalink to &quot;Land Ice Data Collections Overview&quot;">​</a></h2><ul><li>All spatial layers are aligned to one projected epsg:3031 <code>x</code>/<code>y</code> grid. The working grid uses 100 m cells, with <code>x</code> from <code>-2867900</code> to <code>2867900</code> and <code>y</code> from <code>-2457900</code> to <code>2457900</code>, giving 57,358 columns by 49,158 rows.</li><li>The same <code>x, y</code> position refers to the same place across every variable.</li><li>Some datasets already closely match the target grid. Others had to to be reprojected, shifted, resampled and interpolated. The default interpolation method is <strong>nearest neighbour</strong>.</li><li>Vector datasets are converted into raster variables by burning their geometries onto the target grid.</li></ul>',4)])])}const u=a(i,[["render",n]]);export{p as __pageData,u as default};
